insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('avatars','avatars',true,5242880,array['image/jpeg','image/png','image/webp','image/gif']),('products','products',true,10485760,array['image/jpeg','image/png','image/webp']),('gallery','gallery',true,52428800,array['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm']),('backgrounds','backgrounds',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy storage_public_read on storage.objects for select using(bucket_id in ('avatars','products','gallery','backgrounds'));
create policy storage_owner_insert on storage.objects for insert to authenticated with check(bucket_id in ('avatars','products','gallery','backgrounds') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy storage_owner_update on storage.objects for update to authenticated using(bucket_id in ('avatars','products','gallery','backgrounds') and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id in ('avatars','products','gallery','backgrounds') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy storage_owner_delete on storage.objects for delete to authenticated using(bucket_id in ('avatars','products','gallery','backgrounds') and (storage.foldername(name))[1]=(select auth.uid())::text);
